def finds_3corner_L(grid, r, c, target_color):
    """Find if a 2x2 with 3 corners of target_color and 1 different exists, where
    the different one is at position (r,c)."""
    for sr in range(r-1, r+2):
        for sc in range(c-1, c+2):
            if sr >= 0 and sr < len(grid) and sc >= 0 and sc < len(grid[0]):
                corners = [
                    (sr, sc),
                    (sr, sc+1),
                    (sr+1, sc),
                    (sr+1, sc+1)
                ]
                if len(corners) != 4:
                    continue
                values = [grid[cr][cc] for cr, cc in corners if 0 <= cr < len(grid) and 0 <= cc < len(grid[0])]
                if len(values) == 4:
                    my_pos = 0
                    for i, (cr, cc) in enumerate(corners):
                        if cr == r and cc == c:
                            my_pos = i
                        break
                    others = [v for i, v in enumerate(values) if i != my_pos]
                    if len(others) == 3 and all(o == target_color for o in others):
                        return True
    return False

